import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import type { BulkFile } from '../../../src/market-data/binance-vision.js';
import type { CsvLine } from '../../../src/market-data/bulk-csv.js';
import {
  storedRows,
  type CandleSink,
  type StoredCandle,
  type StoredQuarantine,
  type WriteResult,
} from '../../../src/market-data/bulk-loader.js';
import type { KlineBatch } from '../../../src/market-data/validator.js';
import type { HttpGet } from '../../../src/market-data/vision-http.js';
import type {
  BoundedGetLimits,
  BoundedGetResult,
} from '../../../src/shared/bounded-fetch.js';
import { zipOf } from './zip-writer.js';

// Synthetic bulk-file fixtures for the S1b loader tests. Nothing here was
// fetched: the CSV text is generated by integer arithmetic or committed, and
// archives are built in memory by the test-only zip writer.

const here = import.meta.dirname;
const encoder = new TextEncoder();

/** The committed 96-row day, BTCUSDT 15m 2026-10-01, µs times. */
export const DAY_FIXTURE = 'btcusdt-15m-2026-10-01-day.csv';

export function readFixture(name: string): string {
  return readFileSync(join(here, name), 'utf8');
}

export const DAY_MS = 24 * 60 * 60 * 1000;
export const STEP_MS = 15 * 60 * 1000;
export const SLOTS_PER_DAY = 96;

/** Hundredths as a price string with eight decimals. */
export function price(cents: number): string {
  const whole = Math.floor(cents / 100);
  const fraction = String(cents % 100).padStart(2, '0');
  return `${whole}.${fraction}000000`;
}

export interface BarCents {
  readonly open: number;
  readonly high: number;
  readonly low: number;
  readonly close: number;
}

/** One bulk CSV line in µs for a 15m bar from integer hundredths. */
export function klineLine(
  openTimeMs: number,
  bar: BarCents,
  stepMs = STEP_MS,
): string {
  return [
    `${openTimeMs}000`,
    price(bar.open),
    price(bar.high),
    price(bar.low),
    price(bar.close),
    '10.00000000',
    `${openTimeMs + stepMs - 1}999`,
    '600000.00000000',
    '100',
    '5.00000000',
    '300000.00000000',
    '0',
  ].join(',');
}

/**
 * A deterministic quiet random walk: each bar opens at the last close and
 * moves at most 0.30 either way, with a range of up to 0.60 more.
 */
export function walk(
  count: number,
  seed: number,
  startCents = 6_000_000,
): BarCents[] {
  let state = seed >>> 0;
  const next = (modulo: number): number => {
    state = (Math.imul(state, 1_103_515_245) + 12_345) >>> 0;
    return (state >>> 8) % modulo;
  };
  const bars: BarCents[] = [];
  let close = startCents;
  for (let index = 0; index < count; index += 1) {
    const open = close;
    close = open + next(61) - 30;
    const high = Math.max(open, close) + next(31);
    const low = Math.min(open, close) - next(31);
    bars.push({ open, high, low, close });
  }
  return bars;
}

/** `count` consecutive bar lines from `fromMs`. */
export function walkLines(
  fromMs: number,
  count: number,
  seed: number,
  stepMs = STEP_MS,
): string[] {
  return walk(count, seed).map((bar, index) =>
    klineLine(fromMs + index * stepMs, bar, stepMs),
  );
}

export function csvText(lines: readonly string[]): string {
  return lines.map((line) => `${line}\n`).join('');
}

export function sha256Hex(bytes: Uint8Array): string {
  return createHash('sha256').update(bytes).digest('hex');
}

export function checksumBody(zip: Uint8Array, zipName: string): Uint8Array {
  return encoder.encode(`${sha256Hex(zip)}  ${zipName}\n`);
}

export type FakeResponse =
  | { readonly status: number; readonly body?: Uint8Array }
  | { readonly fail: 'timeout' | 'too_large' | 'redirect' | 'network' };

/** A recording fake `HttpGet`: a map from URL to response, 404 otherwise. */
export class FakeHttp implements HttpGet {
  readonly requests: { url: string; limits: BoundedGetLimits }[] = [];
  readonly responses = new Map<string, FakeResponse>();

  get(url: string, limits: BoundedGetLimits): Promise<BoundedGetResult> {
    this.requests.push({ url, limits });
    const response = this.responses.get(url) ?? { status: 404 };
    if ('fail' in response) {
      return Promise.resolve({ ok: false, reason: response.fail });
    }
    const body = response.body ?? new Uint8Array(0);
    if (body.length > limits.maxBytes) {
      return Promise.resolve({ ok: false, reason: 'too_large' });
    }
    return Promise.resolve({ ok: true, status: response.status, body });
  }

  /** Serves `file` as a zip of `text`, with a correct CHECKSUM. */
  serve(file: BulkFile, text: string | Uint8Array): Uint8Array {
    const zip = zipOf(file.csvName, text);
    this.responses.set(file.zipUrl, { status: 200, body: zip });
    this.responses.set(file.checksumUrl, {
      status: 200,
      body: checksumBody(zip, file.zipName),
    });
    return zip;
  }

  urls(): string[] {
    return this.requests.map(({ url }) => url);
  }
}

export interface SinkCall {
  readonly file: BulkFile;
  readonly batch: KlineBatch;
  readonly lines: readonly CsvLine[];
  readonly candles: StoredCandle[];
  readonly quarantine: StoredQuarantine[];
}

/** A recording fake `CandleSink`: stores nothing, reports every candle inserted. */
export class RecordingSink implements CandleSink {
  readonly calls: SinkCall[] = [];

  storeFile(
    file: BulkFile,
    batch: KlineBatch,
    lines: readonly CsvLine[],
  ): Promise<WriteResult> {
    const rows = storedRows(file, batch, lines);
    this.calls.push({ file, batch, lines, ...rows });
    return Promise.resolve({
      inserted: rows.candles.length,
      alreadyStored: 0,
      storedConflicts: 0,
    });
  }
}
